// One ESLint config for the whole repo (`pnpm lint`). The custom rules are the no-raw-invoke
// rule and the import boundaries from CLAUDE.md.
import js from "@eslint/js"
import globals from "globals"
import reactHooks from "eslint-plugin-react-hooks"
import tseslint from "typescript-eslint"

export default tseslint.config(
  // Never lint build output or generated files.
  {
    ignores: [
      "**/dist/**",
      "**/target/**",
      "**/node_modules/**",
      "**/src-tauri/gen/**",
      "apps/bar/src/shared/bindings.ts", // generated by tauri-specta
      "packages/sdk/src/protocol.ts", // generated from crates/protocol
    ],
  },

  js.configs.recommended,
  tseslint.configs.recommended,

  // Scripts and config files run in Node.
  {
    files: ["**/*.{js,mjs,ts}"],
    languageOptions: { globals: globals.node },
  },

  // The bar's React frontend runs in the browser.
  {
    files: ["apps/bar/src/**/*.{ts,tsx}"],
    languageOptions: { globals: globals.browser },
    plugins: { "react-hooks": reactHooks },
    rules: {
      "react-hooks/rules-of-hooks": "error",
      // Never call Tauri's invoke directly: use the generated `commands` from shared/bindings.
      "no-restricted-imports": [
        "error",
        {
          paths: [
            {
              name: "@tauri-apps/api/core",
              importNames: ["invoke"],
              message: "Don't call invoke directly. Use `commands` from @/shared/bindings.",
            },
          ],
        },
      ],
    },
  },

  // The SDK never imports Tauri, and nothing outside apps/ imports from apps/.
  {
    files: ["packages/**/*.ts", "examples/**/*.ts"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            { group: ["@tauri-apps/*"], message: "The SDK and examples never import Tauri." },
            { group: ["**/apps/**"], message: "Nothing imports from apps/." },
          ],
        },
      ],
    },
  },
)
